package presentation

import v "github.com/Naenier/ED-Copilot/internal/value"

func RanksPage(state M) Page {
	p := Page{Title: "Ранги", Description: "Прогресс командира, способы повышения и доступные награды.", Columns: []string{"Направление ранга", "Ранг", "Следующий ранг", "Прогресс, %"}, Rows: []Row{}}
	for _, rank := range v.Rows(v.At(state, "ranks", "disciplines")) {
		p.Rows = append(p.Rows, row(rank, []string{v.Text(rank["title"], "—"), v.Text(rank["rankName"], "—"), v.Text(rank["nextRankName"], "—"), Number(rank["progressPercent"])}, ""))
	}
	return p
}

func PoliticsPage(state M) Page {
	p := Page{Title: "Политика", Columns: []string{"Система", "Состояние"}, Modes: []string{"Политика", "Цели сообщества", "Пауэрплей"}, Rows: []Row{}}
	active := v.Obj(v.At(state, "politics", "activeSystem"))
	hasFactions := false
	for _, faction := range v.Rows(v.At(active, "factions", "entries")) {
		hasFactions = hasFactions || v.Str(faction["name"]) != ""
	}
	for _, conflict := range v.Rows(v.At(active, "conflicts", "entries")) {
		hasFactions = hasFactions || (v.Str(v.At(conflict, "faction1", "name")) != "" && v.Str(v.At(conflict, "faction2", "name")) != "")
	}
	if hasFactions {
		p.Modes = append(p.Modes, "Фракции и конфликты")
	}
	for _, system := range v.Rows(v.At(state, "politics", "systems")) {
		p.Rows = append(p.Rows, row(system, []string{v.Text(system["name"], "—"), v.Text(v.At(system, "powerplay", "state"), v.At(system, "info", "state"), "—")}, ""))
	}
	return p
}

